import java.util.*;import java.io.*;public class Main {    static int T;    static int N;    static final int ROOT = 1;    static final int MAX = 10 * 10000 + 5;    static int unused;    static int[][] nxt;    static boolean[] check;    static StringBuilder answerSB = new StringBuilder();    public static void main(String[] args) throws IOException {        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));        T = Integer.parseInt(br.readLine());        while(T-- > 0) {            unused = 2;            nxt = new int[MAX][10];            check = new boolean[MAX];            boolean isFailed = false;            ArrayList<String> phoneNumberArr = new ArrayList<>();            for(int i = 0; i < MAX; i++) {                Arrays.fill(nxt[i], -1);            }            N = Integer.parseInt(br.readLine());            for(int i = 0; i < N; i++) {                phoneNumberArr.add(br.readLine());            }            phoneNumberArr.sort((o1, o2) -> {               return o1.length() - o2.length();            });            for(String pNum : phoneNumberArr) {                if(!insert(pNum)) {                    isFailed = true;                    break;                }            }            if(isFailed) {                answerSB.append("NO").append('\n');            }else {                answerSB.append("YES").append('\n');            }        }        System.out.print(answerSB.toString());    }    public static boolean insert(String pNum) {        int cur = ROOT;        for(int i = 0; i < pNum.length(); i++) {            if(check[cur]) {                return false;            }            char ch = pNum.charAt(i);            if(nxt[cur][c2i(ch)] == -1) {                nxt[cur][c2i(ch)] = unused++;            }            cur = nxt[cur][c2i(ch)];        }        check[cur] = true;        return true;    }    public static int c2i(char ch) {        return ch - '0';    }}